// N8N-OPS-02: Initialize Dead-Man Sentinel State
// Deterministic monitoring — NO LLM required.
// Watches scheduled/critical workflows for execution failures and missing runs.
// SELF-MONITORING LOOP PROTECTION: Sentinel never monitors itself.

const SCHEMA_VERSION = '1.0';
const PROJECT_ID = 'ghiw-n8n-ops-control-plane';

// Watchlist: workflows to monitor with expected cadence
const WATCHLIST = [
  { workflow_id: '8kUOLhbvyeQSj6BO', name: 'GHIW-01 v2', expected_cadence: 'on_demand', grace_minutes: 0 },
  { workflow_id: 'Sv12QTo56NoPUu2D', name: 'DISPATCH', expected_cadence: 'every_15m', grace_minutes: 30 },
  { workflow_id: 'zgjqWnTfjxOud1A5', name: 'GHIW-02 v1', expected_cadence: 'on_demand', grace_minutes: 0 }
];

// SELF-MONITORING PROTECTION: Exclude Sentinel itself and other ops workflows
const EXCLUDE_WORKFLOW_IDS = [
  'n8n-ops-02-dead-man-sentinel',  // Sentinel itself
  'ghiw-50-evidence-ledger',        // Evidence Ledger (ops)
  'ghiw-60-orphan-watcher',         // Orphan Watcher (ops)
  'n8n-ops-01-gitops-guardian'      // GitOps Guardian (ops)
];

// Bootstrap detection: first run sets baseline, doesn't alert
const IS_BOOTSTRAP = true;  // Set to false after first successful baseline run

const runId = 'w1-ops02-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);

const state = {
  schema_version: SCHEMA_VERSION,
  project_id: PROJECT_ID,
  run_id: runId,
  task_id: 'N8N-OPS-02',
  source: { type: 'schedule', id: new Date().toISOString() },
  workflow: { logical_id: 'N8N-OPS-02', id: $workflow.id, name: $workflow.name },
  execution: { id: $execution.id, started_at: new Date().toISOString() },
  state: 'INIT',
  watchlist: WATCHLIST,
  exclude_workflow_ids: EXCLUDE_WORKFLOW_IDS,
  is_bootstrap: IS_BOOTSTRAP,
  execution_status: {},
  findings: [],
  timestamp: new Date().toISOString()
};

return [{ json: state }];

// N8N-OPS-02: Query n8n Executions
// Simulates querying n8n API for latest execution status per watched workflow.
// In production: calls n8n REST API /api/v1/executions.
// For Wave 1: uses simulated execution data for contract testing.

const state = $input.first().json;
const now = new Date();

// Simulated execution data (in production: from n8n API)
const simulatedExecutions = {};

for (const wf of state.watchlist) {
  // Skip excluded workflows
  if (state.exclude_workflow_ids.includes(wf.workflow_id)) {
    continue;
  }

  // Simulate: all workflows have recent successful executions
  // (Different states for contract testing)
  const lastRun = new Date(now.getTime() - 5 * 60000); // 5 minutes ago

  simulatedExecutions[wf.workflow_id] = {
    workflow_id: wf.workflow_id,
    workflow_name: wf.name,
    last_execution: lastRun.toISOString(),
    last_success: lastRun.toISOString(),
    last_failure: null,
    execution_count: 42,
    failure_count: 0,
    status: 'success',
    expected_cadence: wf.expected_cadence,
    grace_minutes: wf.grace_minutes
  };
}

state.execution_status = simulatedExecutions;
state.state = 'EXECUTIONS_QUERIED';

return [{ json: state }];

// N8N-OPS-02: Compare vs Expected Cadence
// Checks each watched workflow against its expected schedule.
// Detects: FAILED executions, LATE executions, MISSING executions, DISABLED workflows.
// Bootstrap: first run sets baseline, doesn't alert.

const state = $input.first().json;
const now = new Date();
const findings = [];

for (const wf of state.watchlist) {
  // Self-monitoring protection: skip excluded workflows
  if (state.exclude_workflow_ids.includes(wf.workflow_id)) {
    continue;
  }

  const exec = state.execution_status[wf.workflow_id];

  if (!exec) {
    // Workflow in watchlist but no execution data
    if (!state.is_bootstrap) {
      findings.push({
        workflow_id: wf.workflow_id,
        workflow_name: wf.name,
        type: 'UNKNOWN',
        detail: 'No execution data available'
      });
    }
    continue;
  }

  // Check 1: Failed execution?
  if (exec.status === 'error' || exec.last_failure) {
    const lastFailure = exec.last_failure ? new Date(exec.last_failure) : null;
    const failureIsRecent = lastFailure && (now.getTime() - lastFailure.getTime() < 3600000); // 1 hour

    findings.push({
      workflow_id: wf.workflow_id,
      workflow_name: wf.name,
      type: 'FAILED',
      last_failure: exec.last_failure,
      detail: failureIsRecent ? 'Recent execution failure detected' : 'Past execution failure recorded'
    });
    continue;
  }

  // Check 2: Missing execution? (only for scheduled workflows)
  if (wf.expected_cadence !== 'on_demand' && exec.last_execution) {
    const lastExec = new Date(exec.last_execution);
    const expectedIntervalMs = wf.expected_cadence === 'every_15m' ? 15 * 60000 : 30 * 60000;
    const graceMs = wf.grace_minutes * 60000;
    const maxAllowedGap = expectedIntervalMs + graceMs;
    const actualGap = now.getTime() - lastExec.getTime();

    if (actualGap > maxAllowedGap) {
      if (!exec.last_execution || actualGap > maxAllowedGap * 3) {
        findings.push({
          workflow_id: wf.workflow_id,
          workflow_name: wf.name,
          type: 'MISSING_EXECUTION',
          last_execution: exec.last_execution,
          expected_cadence: wf.expected_cadence,
          grace_minutes: wf.grace_minutes,
          gap_minutes: Math.round(actualGap / 60000),
          detail: `Expected execution within ${Math.round(maxAllowedGap / 60000)}min, last was ${Math.round(actualGap / 60000)}min ago`
        });
      } else {
        findings.push({
          workflow_id: wf.workflow_id,
          workflow_name: wf.name,
          type: 'LATE',
          last_execution: exec.last_execution,
          expected_cadence: wf.expected_cadence,
          gap_minutes: Math.round(actualGap / 60000),
          detail: `Execution is ${Math.round(actualGap / 60000)}min late (grace: ${wf.grace_minutes}min)`
        });
      }
      continue;
    }
  }

  // Check 3: Never executed? (only if not bootstrap)
  if (!exec.last_execution && !state.is_bootstrap) {
    findings.push({
      workflow_id: wf.workflow_id,
      workflow_name: wf.name,
      type: 'MISSING_EXECUTION',
      detail: 'Workflow has never been executed'
    });
    continue;
  }

  // Healthy
  findings.push({
    workflow_id: wf.workflow_id,
    workflow_name: wf.name,
    type: 'HEALTHY',
    last_execution: exec.last_execution,
    detail: 'Execution on schedule'
  });
}

state.findings = findings;
state.state = 'COMPARED';

return [{ json: state }];

// N8N-OPS-02: Classify & Produce Sentinel Verdict
// Deterministic overall classification based on findings.
// Bootstrap run → HEALTHY (baseline set), no alerts.

const state = $input.first().json;

// Determine overall decision
let decision = 'HEALTHY';
let reasonCodes = ['EXECUTION_ON_SCHEDULE'];

const problemTypes = state.findings
  .filter(f => f.type !== 'HEALTHY')
  .map(f => f.type);

if (state.is_bootstrap) {
  decision = 'HEALTHY';
  reasonCodes = ['BOOTSTRAP_BASELINE_SET', 'EXECUTION_ON_SCHEDULE'];
} else if (problemTypes.length === 0) {
  decision = 'HEALTHY';
  reasonCodes = ['EXECUTION_ON_SCHEDULE'];
} else if (problemTypes.includes('FAILED')) {
  decision = 'FAILED';
  reasonCodes = ['EXECUTION_FAILED'];
} else if (problemTypes.includes('MISSING_EXECUTION')) {
  decision = 'MISSING_EXECUTION';
  reasonCodes = ['EXECUTION_NEVER_OCCURRED'];
} else if (problemTypes.includes('LATE')) {
  decision = 'LATE';
  reasonCodes = ['EXECUTION_OVERDUE', 'GRACE_PERIOD_ACTIVE'];
} else {
  decision = 'UNKNOWN';
  reasonCodes = ['WORKFLOW_NOT_IN_WATCHLIST'];
}

// Count healthy vs problems
const healthyCount = state.findings.filter(f => f.type === 'HEALTHY').length;
const problemCount = problemTypes.length;

// Build output envelope
const output = {
  schema_version: state.schema_version,
  project_id: state.project_id,
  run_id: state.run_id,
  task_id: state.task_id,
  source: state.source,
  workflow: state.workflow,
  execution: { ...state.execution, completed_at: new Date().toISOString() },
  decision: decision,
  reason_codes: reasonCodes,
  evidence_refs: [],
  classification: decision === 'HEALTHY' ? 'GREEN' : (decision === 'LATE' ? 'AMBER' : 'RED'),
  timestamp: new Date().toISOString(),
  sentinel_details: {
    is_bootstrap: state.is_bootstrap,
    workflows_watched: state.watchlist.length,
    workflows_checked: state.findings.length,
    healthy_count: healthyCount,
    problem_count: problemCount,
    excluded_count: state.exclude_workflow_ids.length,
    findings: state.findings
  }
};

return [{ json: output }];

